-- Research ingest staging (external bot). Staging only: nothing here touches live/public tables.
create table public.ingest_settings (key text primary key, value text not null, updated_at timestamptz not null default now());

create table public.ingest_keys (
  id uuid primary key default gen_random_uuid(),
  name text not null unique,
  key_hash text not null unique,          -- sha256 hex of raw key; raw key never stored
  active boolean not null default true,
  created_at timestamptz not null default now(),
  last_used_at timestamptz,
  rate_limit_per_min int not null default 30);

create table public.ingest_rate (key_id uuid references public.ingest_keys on delete cascade, minute timestamptz, n int not null default 0, primary key (key_id, minute));

create table public.research_queue (
  registry_id text primary key,
  name text not null, website text, country text, state text, hq_city text, sec_crd text, lei text,
  priority int not null,
  status text not null default 'queued' check (status in ('queued','claimed','submitted','failed','accepted','rejected')),
  claimed_by text, claimed_at timestamptz, attempts int not null default 0, last_error text,
  submitted_at timestamptz, updated_at timestamptz not null default now());
create index research_queue_next on public.research_queue (status, priority);

create table public.research_submissions (
  id bigint generated always as identity primary key,
  registry_id text not null references public.research_queue,
  bot_id text, payload jsonb, record_count int, valid boolean not null, errors jsonb,
  received_at timestamptz not null default now());
create index research_submissions_firm on public.research_submissions (registry_id);
create index research_submissions_time on public.research_submissions (received_at);

do $$ declare t text; begin
  foreach t in array array['ingest_settings','ingest_keys','ingest_rate','research_queue','research_submissions'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on public.%I from anon, authenticated, public', t);
  end loop; end $$;
-- no policies => anon/authenticated get nothing; service_role bypasses RLS

-- auth + rate limit: returns json {ok, key_id, error}
create function public.ingest_auth(p_hash text) returns jsonb language plpgsql security definer set search_path = public as $$
declare k ingest_keys; m timestamptz := date_trunc('minute', now()); c int;
begin
  select * into k from ingest_keys where key_hash = p_hash and active;
  if not found then return jsonb_build_object('ok',false,'error','unauthorized'); end if;
  if coalesce((select value from ingest_settings where key='ingest_paused'),'false') = 'true' then
    return jsonb_build_object('ok',false,'error','paused'); end if;
    on conflict (key_id, minute) do update set n = r.n + 1 returning n into c;
  delete from ingest_rate where minute < now() - interval '1 hour';
  update ingest_keys set last_used_at = now() where id = k.id;
  if c > k.rate_limit_per_min then return jsonb_build_object('ok',false,'error','rate_limited'); end if;
  return jsonb_build_object('ok',true,'key_id',k.id);
end $$;

create function public.research_claim(p_bot text, p_count int) returns setof public.research_queue
language plpgsql security definer set search_path = public as $$
begin
  -- auto-release stale claims (>2h)
  update research_queue set status='queued', claimed_by=null, claimed_at=null,
    last_error = 'claim expired (' || coalesce(claimed_by,'?') || ')', updated_at=now()
   where status='claimed' and claimed_at < now() - interval '2 hours';
  return query
  update research_queue q set status='claimed', claimed_by=p_bot, claimed_at=now(), updated_at=now()
   where q.registry_id in (select registry_id from research_queue where status='queued'
                           order by priority limit greatest(1, least(p_count,5)) for update skip locked)
  returning q.*;
end $$;

-- store a submission; p_valid=false => failed (+requeue if attempts<3)
create function public.research_submit(p_id text, p_bot text, p_payload jsonb, p_count int, p_valid boolean, p_errors jsonb)
returns jsonb language plpgsql security definer set search_path = public as $$
declare q research_queue; s_id bigint;
begin
  select * into q from research_queue where registry_id = p_id for update;
  if not found then return jsonb_build_object('ok',false,'error','unknown registry_id'); end if;
  if q.status not in ('claimed','queued') or q.claimed_by is distinct from p_bot then
    return jsonb_build_object('ok',false,'error','firm not claimed by this bot_id (status '||q.status||')'); end if;
    values (p_id, p_bot, p_payload, p_count, p_valid, p_errors) returning id into s_id;
  if p_valid then
    update research_queue set status='submitted', submitted_at=now(), last_error=null, updated_at=now() where registry_id=p_id;
    return jsonb_build_object('ok',true,'submission_id',s_id,'status','submitted');
  else
    -- invalid: attempts++, back to queue (claimed_by kept so the same bot may fix and resubmit right away), failed at 3
    update research_queue set attempts=attempts+1, last_error=left(p_errors::text,2000), updated_at=now(), claimed_at=null,
      status = case when attempts+1 >= 3 then 'failed' else 'queued' end
     where registry_id=p_id returning * into q;
    return jsonb_build_object('ok',false,'submission_id',s_id,'status',q.status,'attempts',q.attempts);
  end if;
end $$;

create function public.research_fail(p_id text, p_bot text, p_reason text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare q research_queue;
begin
  update research_queue set attempts=attempts+1, last_error=left(coalesce(p_reason,'(no reason)'),2000),
    status = case when attempts+1 >= 3 then 'failed' else 'queued' end,
    claimed_by=null, claimed_at=null, updated_at=now()
   where registry_id=p_id and status='claimed' and claimed_by = p_bot returning * into q;
  if not found then return jsonb_build_object('ok',false,'error','firm not claimed by this bot_id'); end if;
  return jsonb_build_object('ok',true,'status',q.status,'attempts',q.attempts);
end $$;

create function public.research_status() returns jsonb language sql security definer set search_path = public as $$
  select coalesce(jsonb_object_agg(status, n),'{}'::jsonb) from (select status, count(*) n from research_queue group by 1) s $$;

create function public.ingest_progress() returns jsonb language sql security definer set search_path = public as $$
  select jsonb_build_object(
    'by_status', (select coalesce(jsonb_object_agg(status, n),'{}'::jsonb) from (select status, count(*) n from research_queue group by 1) s),
    'queue_total', (select count(*) from research_queue),
    'submissions_last_hour', (select count(*) from research_submissions where received_at > now() - interval '1 hour'),
    'invalid_last_hour', (select count(*) from research_submissions where received_at > now() - interval '1 hour' and not valid),
    'error_rate_last_hour', (select round(avg(case when valid then 0 else 1 end)::numeric, 3) from research_submissions where received_at > now() - interval '1 hour'),
    'submissions_total', (select count(*) from research_submissions),
    'records_total', (select coalesce(sum(record_count),0) from research_submissions where valid),
    'stale_claims', (select count(*) from research_queue where status='claimed' and claimed_at < now() - interval '2 hours'),
    'paused', (select value from ingest_settings where key='ingest_paused'),
    'db_size_bytes', pg_database_size(current_database()),
    'db_size', pg_size_pretty(pg_database_size(current_database())),
    'submissions_size', pg_size_pretty(pg_total_relation_size('public.research_submissions'))) $$;

do $$ declare f text; begin
  foreach f in array array['ingest_auth(text)','research_claim(text,int)','research_submit(text,text,jsonb,int,boolean,jsonb)',
    'research_fail(text,text,text)','research_status()','ingest_progress()'] loop
    execute format('revoke all on function public.%s from public, anon, authenticated', f);
    execute format('grant execute on function public.%s to service_role', f);
  end loop; end $$;

-- queue: registry rows except status=loaded; b001 first, then gross assets desc
